/*! chromokit 0.1.0 · MIT · https://github.com/js2264/chromokit · generated by scripts/build.mjs — do not edit; put local changes in your own stylesheet */
/*
 * chromokit theme: light, dark, or the system's.
 *
 * Load it in <head>, without `defer`, so the stored choice is on <html>
 * before the first paint and a dark-mode reader never sees a white flash:
 *
 *     <script src="chromokit/theme.js"></script>
 *
 * "System" is the absence of an override, not a third palette: the stylesheet
 * already answers `prefers-color-scheme`, so the script writes
 * `data-theme="light" | "dark"` on <html> for an explicit choice and removes
 * it for the system's. It also writes `data-cx-theme` (always set, including
 * "system") for the toggle's icon, and mirrors the choice to `data-bs-theme`
 * when the page is a Bootstrap one that already carries that attribute.
 *
 * Any element with `data-cx-theme-toggle` cycles system → dark → light (or
 * system → light → dark on a dark machine, so the first press always changes
 * what is on screen). The choice lives in localStorage under
 * `<html data-cx-theme-key="…">`, by default "chromokit:theme".
 */
;(() => {
  if (window.chromokitTheme) return
  const root = document.documentElement
  const KEY = root.getAttribute('data-cx-theme-key') || 'chromokit:theme'
  const media = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null

  const read = () => {
    try {
      const value = window.localStorage.getItem(KEY)
      return value === 'light' || value === 'dark' ? value : 'system'
    } catch {
      return 'system'
    }
  }

  const resolved = (choice) => (choice === 'system' ? (media && media.matches ? 'dark' : 'light') : choice)

  const apply = (choice) => {
    root.setAttribute('data-cx-theme', choice)
    if (choice === 'system') root.removeAttribute('data-theme')
    else root.setAttribute('data-theme', choice)
    if (root.hasAttribute('data-bs-theme')) root.setAttribute('data-bs-theme', resolved(choice))
    for (const button of document.querySelectorAll('[data-cx-theme-toggle]')) {
      const label = `Theme: ${choice}${choice === 'system' ? ` (${resolved(choice)})` : ''}`
      button.setAttribute('title', label)
      button.setAttribute('aria-label', label)
    }
  }

  const set = (choice) => {
    try {
      if (choice === 'system') window.localStorage.removeItem(KEY)
      else window.localStorage.setItem(KEY, choice)
    } catch {
      /* private mode: the choice lasts for this page only */
    }
    apply(choice)
  }

  const next = () => {
    const current = read()
    const order = media && media.matches ? ['system', 'light', 'dark'] : ['system', 'dark', 'light']
    return order[(order.indexOf(current) + 1) % order.length]
  }

  apply(read())
  if (media && media.addEventListener) media.addEventListener('change', () => apply(read()))

  document.addEventListener('click', (event) => {
    const button = event.target instanceof Element ? event.target.closest('[data-cx-theme-toggle]') : null
    if (button) set(next())
  })
  document.addEventListener('DOMContentLoaded', () => apply(read()))

  window.chromokitTheme = { get: read, set, resolved: () => resolved(read()) }
})()
